/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] gray_out;

  TopModule dut(.clk(clk), .rst_n(rst_n), .gray_out(gray_out));

  always #5 clk = ~clk;

  function automatic [3:0] gray2bin(input [3:0] g);
    begin
      gray2bin[3] = g[3];
      gray2bin[2] = g[3] "'^ g[2];
      gray2bin[1] = g[3] ''^ g[2] ''^ g[1];
      gray2bin[0] = g[3] ''^ g[2] ''^ g[1] ''^ g[0];
    end
  endfunction

  integer i;
  initial begin
    $display("time clk rst_n gray bin");
    $monitor("%4t  %0b    %0b    %04b %04b", $time, clk, rst_n, gray_out, gray2bin(gray_out));
    #2 rst_n = 0;
    #8 rst_n = 1;
    for (i = 0; i < 12; i = i + 1) #10;
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

